import type { SyntheticEvent } from "react";

import { cn } from "~/lib/utils";

import type { SocialPostPreviewMedia } from "~/lib/social-post-preview-types";

/**
 * Renders ONE media item across the whole matrix, so every chrome shows media the same way:
 *
 * - **image** → `<img>`
 * - **video with a thumbnail** → `<img>` of the thumbnail (no browser `<video>` UI; the chrome
 *   draws its own play badge)
 * - **video without a thumbnail** → `<video preload="metadata">` (its own first frame shows; an
 *   `<img>` would try to load the `.mp4` as an image and break). Its native controls/overlay are
 *   suppressed so only the chrome's play badge shows.
 *
 * Media is URL-only here — a local `File`/`Blob` is materialized into an object URL upstream (at
 * the {@link SocialPostPreview} boundary), so this component stays a pure renderer.
 *
 * It renders only the media element (`object-cover` by default); chromes own the frame, the
 * aspect ratio, and any play-badge overlay. `onDimensions` reports the natural size once known
 * (from `<img>` load or `<video>` metadata) for chromes that size to the media (Instagram).
 */
export function SocialPostPreviewMediaItem({
  media,
  className,
  onDimensions,
}: {
  media: SocialPostPreviewMedia;
  className?: string;
  onDimensions?: (width: number, height: number) => void;
}) {
  if (media.kind === "video") {
    // Prefer the poster still (a thumbnail) as a plain image — no native <video> chrome.
    if (media.src) {
      return (
        <img
          src={media.src}
          alt=""
          className={cn("size-full object-cover", className)}
          onLoad={dimensionHandler(onDimensions)}
        />
      );
    }
    // No thumbnail: show the video's own first frame; hide native UI.
    if (!media.videoSrc) return null;
    return (
      <video
        src={media.videoSrc}
        muted
        playsInline
        preload="metadata"
        className={cn(
          "size-full object-cover",
          "[&::-webkit-media-controls]:hidden [&::-webkit-media-controls-start-playback-button]:hidden",
          className,
        )}
        onLoadedMetadata={
          onDimensions
            ? (event) => {
                const el = event.currentTarget;
                if (el.videoWidth && el.videoHeight) {
                  onDimensions(el.videoWidth, el.videoHeight);
                }
              }
            : undefined
        }
      />
    );
  }

  if (!media.src) return null;
  return (
    <img
      src={media.src}
      alt=""
      className={cn("size-full object-cover", className)}
      onLoad={dimensionHandler(onDimensions)}
    />
  );
}

function dimensionHandler(onDimensions?: (w: number, h: number) => void) {
  if (!onDimensions) return undefined;
  return (event: SyntheticEvent<HTMLImageElement>) => {
    const el = event.currentTarget;
    if (el.naturalWidth && el.naturalHeight) {
      onDimensions(el.naturalWidth, el.naturalHeight);
    }
  };
}

import { cn } from "~/lib/utils";
import { Play } from "lucide-react";

import type { SocialPostPreviewMedia } from "~/lib/social-post-preview-types";
import { SocialPostPreviewMediaItem } from "./social-post-preview-media";

/**
 * Shared media grid for the timeline chromes (Facebook / LinkedIn / Threads / Bluesky): one
 * image full-width, or 2–4 in the familiar collage, with a "+N" overlay past four and a play
 * badge over a video. `rounded` toggles the corner treatment (Threads/Bluesky round the
 * collage; Facebook/LinkedIn run it edge to edge).
 */
export function FeedMediaGrid({
  media,
  rounded = false,
  className,
}: {
  media: SocialPostPreviewMedia[];
  rounded?: boolean;
  className?: string;
}) {
  const items = media.slice(0, 4);
  const count = items.length;
  const overflow = media.length - items.length;
  if (count === 0) return null;

  return (
    <div
      className={cn(
        "grid gap-[0.15em] overflow-hidden",
        rounded && "rounded-[0.6em] border border-border",
        count === 1 && "grid-cols-1",
        count === 2 && "grid-cols-2",
        count >= 3 && "grid-cols-2 grid-rows-2",
        className,
      )}
    >
      {items.map((item, index) => (
        <div
          key={item.id}
          className={cn(
            "relative bg-muted",
            count === 1 && "aspect-[4/3]",
            count === 3 && index === 0 && "row-span-2 h-full",
            (count === 2 || (count === 3 && index !== 0) || count >= 4) &&
              "aspect-square",
          )}
        >
          <SocialPostPreviewMediaItem media={item} />

          {item.kind === "video" ? (
            <span className="absolute inset-0 grid place-items-center">
              <span className="grid size-[2em] place-items-center rounded-full bg-black/55 text-white [&_svg]:size-[1.1em]">
                <Play aria-hidden />
              </span>
            </span>
          ) : null}

          {overflow > 0 && index === items.length - 1 ? (
            <span className="absolute inset-0 grid place-items-center bg-black/50 text-[1.4em] font-semibold text-white">
              +{overflow}
            </span>
          ) : null}
        </div>
      ))}
    </div>
  );
}

import type { SocialPostPreviewMedia } from "~/lib/social-post-preview-types";

/**
 * The flat media props every chrome's `…Media` layer accepts, so a hand-composer passes plain
 * URLs — `imageSrc` for stills, `videoSrc` (+ `thumbnailSrc` poster) for clips — instead of
 * building a {@link SocialPostPreviewMedia} object. Each prop takes one URL or an array, so a
 * single-media surface and a grid / carousel use the SAME prop. The composed chrome
 * (descriptor-driven) keeps full per-item fidelity; these props are the by-hand ergonomic layer.
 */
export interface SocialPostPreviewFlatMediaProps {
  /** Still image URL(s) — one for single-media surfaces, several for a grid / carousel / collage. */
  imageSrc?: string | string[];
  /** Playable video URL(s). */
  videoSrc?: string | string[];
  /** Video poster / thumbnail still(s), paired by index with `videoSrc`. */
  thumbnailSrc?: string | string[];
}

/** One URL or an array of URLs → an array of URLs (nullish → empty). */
function toArray(value?: string | string[]): string[] {
  if (value == null) return [];
  return Array.isArray(value) ? value : [value];
}

/**
 * Flat scalar props → the normalized {@link SocialPostPreviewMedia} list the internal renderers
 * consume. Any `videoSrc` / `thumbnailSrc` yields video items (poster = `thumbnailSrc`, paired by
 * index); otherwise `imageSrc` becomes image items. Ids are synthesized for keys.
 */
export function flatMediaToList({
  imageSrc,
  videoSrc,
  thumbnailSrc,
}: SocialPostPreviewFlatMediaProps): SocialPostPreviewMedia[] {
  const videos = toArray(videoSrc);
  const posters = toArray(thumbnailSrc);
  if (videos.length || posters.length) {
    return Array.from({ length: Math.max(videos.length, posters.length) }, (_, i) => ({
      id: `flat-video-${i}`,
      kind: "video",
      src: posters[i],
      videoSrc: videos[i],
    }));
  }
  return toArray(imageSrc)
    .filter(Boolean)
    .map((src, index) => ({ id: `flat-image-${index}`, kind: "image", src }));
}

/** The first normalized item, for single-media surfaces (verticals, Pinterest, YouTube Watch). */
export function flatMediaToItem(
  props: SocialPostPreviewFlatMediaProps,
): SocialPostPreviewMedia | undefined {
  return flatMediaToList(props)[0];
}
